type Order = { id: string; totalCents: number };
type SaveResult =
  | { ok: true; orderId: string }
  | { ok: false; reason: 'validation' | 'network'; message: string };
type SaveOrder = (order: Order) => Promise<SaveResult>;
type SendReceipt = (order: Order) => Promise<void>;

async function submitOrder(
  order: Order,
  saveOrder: SaveOrder,
  sendReceipt: SendReceipt,
) {
  const saved = await saveOrder(order);
  if (!saved.ok) return saved;
  await sendReceipt(order);
  return saved;
}

export function OrderSummary({
  order, onSubmit,
}: { order: Order; onSubmit: (order: Order) => void }) {
  return (
    <section aria-labelledby="order-summary-title">
      <h2 id="order-summary-title">Order {order.id}</h2>
      <p>Total: {order.totalCents}</p>
      <button type="button" onClick={() => onSubmit(order)}>Confirm order</button>
    </section>
  );
}

